from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], *, workers: int | None = None) -> int:
    """Return the sum of square(x) over xs, computing the squares on a thread pool.

    workers sets the ThreadPoolExecutor size; None uses the executor default.
    The result must be identical for every workers value.
    """
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return sum(pool.map(square, xs))


@pytest.mark.parametrize("workers", [1, 2, 4, 8])
def test_sum_squares_same_at_every_worker_count(workers: int) -> None:
    xs = list(range(-50, 51))
    expected = sum(square(x) for x in xs)
    assert sum_squares(xs, workers=workers) == expected


def test_sum_squares_empty() -> None:
    assert sum_squares([]) == 0


def test_sum_squares_small() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_sum_squares_negatives() -> None:
    assert sum_squares([-3, 3]) == 18


def test_sum_squares_default_workers() -> None:
    xs = [4, -5, 6]
    assert sum_squares(xs) == 16 + 25 + 36


def test_sum_squares_large_input_matches_sequential() -> None:
    xs = list(range(-10_000, 10_000))
    expected = sum(square(x) for x in xs)
    assert sum_squares(xs, workers=8) == expected
